const lockSigintProject = `-- name: LockSigintProject :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::text, 1397313108))
`

// Serialize every sigint configuration mutation in a project. The fixed seed
// namespaces this lock independently from other project-scoped subsystems.
func (q *Queries) LockSigintProject(ctx context.Context, projectID string) error {
	_, err := q.db.Exec(ctx, lockSigintProject, projectID)
	return err
}

const replaceSensorSignals = `-- name: ReplaceSensorSignals :exec
WITH input AS (
    SELECT signal_id, (ordinality - 1)::integer AS sort_order
    FROM unnest($3::uuid[]) WITH ORDINALITY AS requested(signal_id, ordinality)
),
updated AS (
    UPDATE sigint_sensor_signals AS member
    SET sort_order = input.sort_order,
        updated_at = clock_timestamp()
    FROM input
    WHERE member.project_id = $1
      AND member.sensor_id = $2
      AND member.signal_id = input.signal_id
      AND member.deleted IS FALSE
    RETURNING member.signal_id
),
deleted AS (
    UPDATE sigint_sensor_signals AS member
    SET deleted_at = clock_timestamp(),
        updated_at = clock_timestamp()
    WHERE member.project_id = $1
      AND member.sensor_id = $2
      AND member.deleted IS FALSE
      AND NOT EXISTS (
          SELECT 1
          FROM input
          WHERE input.signal_id = member.signal_id
      )
    RETURNING member.signal_id
)
INSERT INTO sigint_sensor_signals (
    id,
    project_id,
    sensor_id,
    signal_id,
    sort_order
)
SELECT
    generate_uuidv7(),
    $1,
    $2,
    input.signal_id,
    input.sort_order
FROM input
WHERE NOT EXISTS (
    SELECT 1
    FROM updated
    WHERE updated.signal_id = input.signal_id
)
`

type ReplaceSensorSignalsParams struct {
	ProjectID uuid.UUID
	SensorID  uuid.UUID
	SignalIds []uuid.UUID
}

func (q *Queries) ReplaceSensorSignals(ctx context.Context, arg ReplaceSensorSignalsParams) error {
	_, err := q.db.Exec(ctx, replaceSensorSignals, arg.ProjectID, arg.SensorID, arg.SignalIds)
	return err
}

const saveDefinitionSnapshots = `-- name: SaveDefinitionSnapshots :exec
INSERT INTO sigint_definition_snapshots (project_id, sensor_id, definition_hash, definition)
SELECT $1::uuid, snapshot.sensor_id, snapshot.definition_hash, snapshot.definition
FROM jsonb_to_recordset($2::jsonb) AS snapshot(sensor_id uuid, definition_hash text, definition jsonb)
JOIN projects p ON p.id = $1::uuid AND p.organization_id = $3
ON CONFLICT (project_id, sensor_id, definition_hash) DO NOTHING
`

